7function App() {
8   const [entries, setEntries] = useState([{     id: 1,     title: "First Day at the Job",     date: "FEBRUARY 10, 2026",     content: "Today was my first day at the new job. Everyone was welcoming and helpful.",     author: "John Doe"    }   ]);
9
10
11  function handleAddEntry(title, content) {
12    const newEntry = {
13      id: Date.now(),
14      title,
15      content,
16      date: new Date().toLocaleDateString("en-US", {
17        year: "numeric",
18        month: "short",
19        day: "numeric"
20      }).toUpperCase(),
21      author: "John Doe"
22    };
23
24    setEntries([...entries, newEntry]);
25  }
26
27  return (
28    <div className="layout-root">
29      <div className='main-container'>
30        <Header />
31        <JournalForm onAddEntry={handleAddEntry} />
32        <EntryCard
33          title={entries[0].title}
34          date={entries[0].date}
35          content={entries[0].content}
36          author={entries[0].author}
37        />
38      </div>
39    </div>
40  );
41}
42
43export default App;

